#include <stdio.h>

void unesi(char niz[], int velicina)
{
    int i=0;
    char znak=getchar();
    if (znak=='\n')
        znak=getchar();
    while(i<velicina-1 && znak!='\n')
    {
        niz[i]=znak;
        i++;
        znak=getchar();
    }
    niz[i]='\0';
}

char* kodiraj(char* s, char* t)
{
    int brojac[96]={0},i,j;
    int maxi=0,broj_brojaca=0;
    char ascii[200]={0};
/*formiranje ascii stringa*/
    for(i=0;i<96;i++)
    {
    	if(i==95)
    		*(t+i)='\0';
    	else *(t+i)=i+32;
    }
/*ucestalosti charova*/
    for(i=0;;i++)
    {
    	j=0;
        while(j<95)
        {
            if(*(s+i)==*(t+j))
            {
                brojac[j]++;
                break;
            }
            j++;
        }
        if(*(s+i+1)=='\0')
            break;
    }
/*pronalazenje najucestalijeg*/
	i=0;
    while(i<95)
    {
        if(brojac[i]>maxi)
            maxi=brojac[i];
        i++;
    }
/**/
/*redoslijedom od najucestalijeg*/
    do
    {
        for(i=0;i<95;i++)
        {
            for(j=0;;j++)
            {
                broj_brojaca=0;
                if(brojac[j]==maxi)
                {
                    ascii[i]=*(t+j);
                    if(maxi>0)
                    {
                        if(broj_brojaca==0)
                            i++;
                    }
                    if(maxi==0)
                        i++;
                    broj_brojaca++;
                }
                if(*(t+j)=='\0')
                    break;
            }
            if(broj_brojaca==0)
                i--;
            maxi--;
        }
    }while(maxi>0);
/*pretvaranje u kod*/
    for(i=0;;i++)
    {
        *(t+i)=ascii[i];
        if(ascii[i]=='\0')
            break;
    }
/*sifriranje*/
    for(i=0;;i++)
    {
    	if(*(s+i)=='\0')
        {
            *(s+i)='\0';
            break;
        }
        for(j=0;;j++)
        {
        	if(*(t+j)=='\0')
                break;
            if(*(s+i)==*(t+j))
            {
                *(s+i)=126-j;
                break;
            }
        }
    }
	return s;
}

char* dekodiraj(char* s, char* t)
{
    int i,j;
    for(i=0;*(s+i)!='\0';i++)
    {
        for(j=0;j<95;j++)
        {
            if(*(s+i)==126-j)
            {
                *(s+i)=*(t+j);
                break;
            }
        }
    }
    return s;
}

int main()
{
	char s[1000],kod[150];
	unesi(s,1000);
    printf("%s",kodiraj(s,kod));
    printf("\n%s",dekodiraj(s,kod));
    return 0;
}

#include <stdio.h>
#include <string.h>

/*
 * Ovaj program racuna ukupne troskove obroka za tri osobe: Tarika, Bojana i Mirzu.
 * Svaka osoba bira jedan obrok u tri razlicita restorana: Restoran, Fast-food i Bistro.
 * Obroci su: hamburger, cevapi i pica. Svaki obrok ima svoju cenu u svakom restoranu.
 * Program zatim racuna koji je restoran najjeftiniji za svaku osobu, uzimajuci u obzir
 * moguce popuste. Popusti se primenjuju ako osoba naruci odredjenu kombinaciju obroka.
 * Na kraju program ispisuje koji je restoran najjeftiniji za svaku osobu i koliko kosta.
 */

// Funkcija koja ispisuje cene u svakom restoranu
void ispisiCene(char restoran[], float hamburger, float cevapi, float pica) {
    printf("Cene u %s:\n", restoran);
    printf("  Hamburger: %.2f KM\n", hamburger);
    printf("  Cevapi: %.2f KM\n", cevapi);
    printf("  Pica: %.2f KM\n", pica);
    printf("\n");
}

// Funkcija koja racuna cenu obroka sa popustom
float racunajSaPopustom(float cenaHamburgera, float cenaCevapa, float cenaPice, char izbor[]) {
    float ukupnaCena = 0;

    // Proveravamo sta je osoba izabrala i racunamo cenu
    if (strcmp(izbor, "hamburger") == 0) {
        ukupnaCena = cenaHamburgera;
    } else if (strcmp(izbor, "cevapi") == 0) {
        ukupnaCena = cenaCevapa;
    } else if (strcmp(izbor, "pica") == 0) {
        ukupnaCena = cenaPice;
    } else {
        printf("Greska: Nepoznat izbor obroka!\n");
        return -1;
    }

    // Primenjujemo popust ako je cena veca od 10 KM (10% popusta)
    if (ukupnaCena > 10) {
        printf("  Ostvarujete popust od 10 posto!\n");
        ukupnaCena = ukupnaCena * 0.9; // Oduzimamo 10% od cene
    }

    return ukupnaCena;
}

// Funkcija koja pronalazi najjeftiniji restoran za datu osobu
void nadjiNajjeftiniji(char osoba[], char izbor[], 
                       float ceneRestoran[], float ceneFastfood[], float ceneBistro[]) {
    // Racunamo cene u svakom restoranu sa popustom
    float cenaRestoran = racunajSaPopustom(ceneRestoran[0], ceneRestoran[1], ceneRestoran[2], izbor);
    float cenaFastfood = racunajSaPopustom(ceneFastfood[0], ceneFastfood[1], ceneFastfood[2], izbor);
    float cenaBistro = racunajSaPopustom(ceneBistro[0], ceneBistro[1], ceneBistro[2], izbor);

    printf("\n%s, izabrali ste: %s\n", osoba, izbor);
    printf("  Cena u Restoranu: %.2f KM\n", cenaRestoran);
    printf("  Cena u Fast-foodu: %.2f KM\n", cenaFastfood);
    printf("  Cena u Bistrou: %.2f KM\n", cenaBistro);

    // Poredimo cene i nalazimo najjeftiniju opciju
    // Ovo je kao da uporedjujem ko je najbrzi na takmicenju, samo sa parama
    if (cenaRestoran <= cenaFastfood && cenaRestoran <= cenaBistro) {
        printf("  Najjeftiniji restoran za vas je: Restoran (%.2f KM)\n", cenaRestoran);
    } else if (cenaFastfood <= cenaRestoran && cenaFastfood <= cenaBistro) {
        printf("  Najjeftiniji restoran za vas je: Fast-food (%.2f KM)\n", cenaFastfood);
    } else {
        printf("  Najjeftiniji restoran za vas je: Bistro (%.2f KM)\n", cenaBistro);
    }
}

int main() {
    // Definisemo cene za svaki restoran
    // Cene su u KM (konvertibilne marke)
    float ceneRestoran[3] = {8.5, 12.0, 10.0};  // hamburger, cevapi, pica
    float ceneFastfood[3] = {5.0, 9.0, 7.5};    // hamburger, cevapi, pica
    float ceneBistro[3] = {7.0, 11.0, 9.5};     // hamburger, cevapi, pica

    // Ispisujemo cene za svaki restoran da korisnik vidi
    printf("Dobrodosli u program za racunanje najjeftinijeg obroka!\n");
    printf("=====================================================\n\n");

    ispisiCene("Restoran", ceneRestoran[0], ceneRestoran[1], ceneRestoran[2]);
    ispisiCene("Fast-food", ceneFastfood[0], ceneFastfood[1], ceneFastfood[2]);
    ispisiCene("Bistro", ceneBistro[0], ceneBistro[1], ceneBistro[2]);

    // Tarik bira sta ce jesti
    char tarikovIzbor[] = "hamburger";
    nadjiNajjeftiniji("Tarik", tarikovIzbor, ceneRestoran, ceneFastfood, ceneBistro);

    // Bojan bira sta ce jesti
    char bojanovIzbor[] = "cevapi";
    nadjiNajjeftiniji("Bojan", bojanovIzbor, ceneRestoran, ceneFastfood, ceneBistro);

    // Mirza bira sta ce jesti
    char mirzinIzbor[] = "pica";
