// Ovo je funkcija koja provjerava duzine rijeci
// prima tekst i niz brojeva i broj elemenata
// vraca 1 ako je tacno, 0 ako nije
int provjeriDuzine(char* tekst, int* niz, int brojElemenata) {
    int i = 0; // brojac za prolazak kroz tekst, i=0
    int duzinaRijeci = 0; // duzina trenutne rijeci, pocetna 0
    int indeks = 0; // indeks u nizu, pocinje od 0
    int uRijeci = 0; // da li smo u rijeci, 0 znaci nismo

    // Ovdje se prolazi kroz tekst dok ne dodjemo do kraja
    while (tekst[i] != '\0') {
        // Provjera da li je karakter razmak, tab ili novi red
        if (tekst[i] == ' ' || tekst[i] == '\t' || tekst[i] == '\n') {
            // Ako smo bili u rijeci, onda smo je zavrsili
            if (uRijeci) {
                // Provjera da li indeks nije veci od broja elemenata
                if (indeks >= brojElemenata) {
                    return 0; // Vracamo 0 jer ima vise rijeci nego brojeva
                }
                // Provjera da li je duzina rijeci jednaka broju u nizu
                if (duzinaRijeci != niz[indeks]) {
                    return 0; // Nije tacno, vracamo 0
                }
                // Resetujemo duzinu i uRijeci za novu rijec
                duzinaRijeci = 0;
                uRijeci = 0;
                indeks++; // Povecavamo indeks za sljedeci broj
            }
        } else {
            // Ako nije razmak, onda je dio rijeci
            uRijeci = 1;
            duzinaRijeci++; // Povecava se duzina rijeci za jedan
        }
        i++; // Idemo na sljedeci karakter
    }

    // Nakon petlje, provjeravamo posljednju rijec ako je bila
    if (uRijeci) {
        // Opet provjera indeksa
        if (indeks >= brojElemenata) {
            return 0;
        }
        // Provjera duzine
        if (duzinaRijeci != niz[indeks]) {
            return 0;
        }
        indeks++; // Ovo je posljednja rijec, povecavamo indeks
    }

    // Provjera da li smo obradili tacno onoliko rijeci koliko ima brojeva
    if (indeks != brojElemenata) {
        return 0; // Nije isti broj, vracamo 0
    }

    return 1; // Sve je ok, vracamo 1
}

int main() {
    // Ovdje testiramo funkciju sa primjerom
    char tekst[] = "Ovo je test";
    int niz[] = {3, 2, 4}; // Ovo=3, je=2, test=4
    int broj = 3; // Broj elemenata niza

    int rezultat = provjeriDuzine(tekst, niz, broj);
    printf("Rezultat: %d\n", rezultat); // Stampa se rezultat, treba 1

    // Drugi test, sa pogresnom duzinom
    char tekst2[] = "Dobro jutro";
    int niz2[] = {5, 6}; // Dobro=5, jutro=5, ali niz kaze 6, treba 0
    int rezultat2 = provjeriDuzine(tekst2, niz2, 2);
    printf("Rezultat 2: %d\n", rezultat2); // Stampa se rezultat 2, treba 0

    return 0; // Kraj programa
}

